/* Authenticated role-based shell and server-backed student exam flows. */
let signedInUser = null;
let secureExamActive=false,securityEventBusy=false,lastSecurityEvent={};
let examQuestions=[],examAnswers={},examTimerHandle=null,examCurrentIndex=0,examFinished=false;
const csrf = () => document.cookie.split('; ').find(x => x.startsWith('qb_csrf='))?.split('=').slice(1).join('=') || '';
const nativeFetch = window.fetch.bind(window);
window.fetch = (url, options={}) => {
  const method=(options.method||'GET').toUpperCase();
  const target=typeof url==='string'?url:url.url;
  if (!/^https?:\/\//i.test(target) && !['GET','HEAD','OPTIONS'].includes(method)) {
    options={...options,headers:{...(options.headers||{}),'X-CSRF-Token':decodeURIComponent(csrf())}};
  }
  return nativeFetch(url,options);
};
async function api(url, options={}) {
  const headers={...(options.headers||{})};
  if (options.method && options.method !== 'GET') headers['X-CSRF-Token']=decodeURIComponent(csrf());
  const response=await fetch(url,{...options,headers});
  const data=await response.json().catch(()=>({}));
  if(!response.ok) throw new Error(typeof data.detail==='object'?(data.detail.message||data.detail.reason_code):data.detail||`Request failed (${response.status})`);
  return data;
}
async function enterExamFullscreen(){
  if(window.MeritIQraNative){document.body.dataset.examDisplay='focus';return;}
  if(document.fullscreenElement)return;
  const request=document.documentElement.requestFullscreen||document.documentElement.webkitRequestFullscreen;
  if(!request){document.body.dataset.examDisplay='focus';return;}
  document.body.dataset.examDisplay='fullscreen';
  await Promise.resolve(request.call(document.documentElement));
}
async function recordSecurityViolation(eventType){
  if(!secureExamActive||securityEventBusy)return;
  const now=Date.now();if(now-(lastSecurityEvent[eventType]||0)<1500)return;lastSecurityEvent[eventType]=now;
  const sessionId=$('exam-current-question')?.dataset.session;if(!sessionId)return;
  securityEventBusy=true;
  try{
    const result=await api(`/api/sessions/${sessionId}/security-events`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_type:eventType})});
    if(result.signal_only)return;
    const notice=$('exam-security-notice');if(notice)notice.textContent=`Security warning ${result.violations} of ${result.maximum}: prohibited browser activity was detected and recorded.`;
    notify(`Security warning ${result.violations} of ${result.maximum}. Further violations may submit the exam.`);
    if(result.auto_submitted){secureExamActive=false;clearInterval(examTimerHandle);document.body.classList.remove('exam-focus');if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});notify('Exam automatically submitted after repeated security violations.');showView('my-results');}
  }catch(error){notify('Could not record the security event. Remain on the exam page.');}finally{securityEventBusy=false;}
}
function esc(value){return escapeHtml(value??'');}
function showView(name){
  const digitizationReview=$('pdf-modal');
  if(digitizationReview && name!=='upload-crop') digitizationReview.hidden=true;
  const panels=[...document.querySelectorAll('.tab-panel')];
  panels.forEach(p=>{const active=p.id===`${name}-panel`;p.hidden=!active;p.classList.toggle('active',active);});
  document.querySelectorAll('.sidebar nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));
  if(matchMedia('(max-width:800px)').matches){$('app-shell').classList.remove('nav-open');$('sidebar-toggle').setAttribute('aria-expanded','false');}
  if(name==='dashboard') loadDashboard();
  if(name==='available-exams') loadAvailableExams();
  if(name==='my-exams') loadMyExams();
  if(name==='my-results') loadMyResults();
  if(name==='student-analytics') loadStudentAnalytics();
  if(name==='my-profile') loadStudentProfile();
  if(name==='admin-exams') loadAdminExams();
  if(name==='admin-results') loadAdminResults();
  if(name==='ai-generate' && typeof loadAiGenerationRuns==='function') loadAiGenerationRuns();
  if(name==='exam' && signedInUser?.role==='ADMIN' && typeof loadBlueprintFacets==='function') loadBlueprintFacets();
  if(name==='questions' && signedInUser?.role==='ADMIN'){loadQuestions();loadFacets();}
}
function examCard(e,action){return `<article class="exam-tile"><div><span class="badge">${esc(e.status||e.registration_status)}</span><h3>${esc(e.name)}</h3><p>${esc(e.description||'No description provided.')}</p></div><dl><div><dt>Subject</dt><dd>${esc(e.subject||'General')}</dd></div><div><dt>Level</dt><dd>${esc(e.level||'Open')}</dd></div><div><dt>Duration</dt><dd>${e.duration_minutes} min</dd></div><div><dt>Questions</dt><dd>${e.question_count??'—'}</dd></div></dl>${action||''}</article>`;}
async function loadDashboard(){const d=await api('/api/dashboard');window.loadMentorInsight?.();const admin=signedInUser.role==='ADMIN';$('dashboard-title').textContent=admin?'Administrator dashboard':'Welcome back';const labels={users:'Learners',exams:'Exams',questions:'Questions',attempts:'Attempts',published_exams:'Published',open_exams:'Open now'};const entries=Object.entries(d).filter(([,v])=>typeof v==='number').slice(0,admin?8:6);$('dashboard-metrics').innerHTML=entries.map(([k,v],i)=>`<div class="dashboard-metric tone-${i%6}"><span>${esc(labels[k]||k.replaceAll('_',' '))}</span><strong>${esc(String(v))}</strong><small>${admin?'Platform total':'Your activity'}</small></div>`).join('');const detail=$('dashboard-detail');if(detail&&admin){detail.hidden=false;detail.innerHTML='<article><span class="dashboard-detail-icon">✓</span><div><strong>Admin workspace ready</strong><p>Review exam operations, learner outcomes, and content quality from the compact workspace.</p></div></article><article><span class="dashboard-detail-icon">↗</span><div><strong>Next actions</strong><p>Use Exam Admin for publishing and registrations, then Performance Lab for outcome trends.</p></div></article>';}}
async function loadAvailableExams(){const rows=await api('/api/exams');$('available-exams-list').innerHTML=rows.map(e=>examCard(e,`<button class="primary" data-enroll="${e.id}">Register / Enroll</button>`)).join('')||'<p class="empty-state">No exams are open now. An administrator must open an exam before it appears here.</p>';}
async function loadMyExams(){const rows=await api('/api/my/exams');const now=Date.now()/1000;$('my-exams-list').innerHTML=rows.map(e=>{let action;if(e.latest_session_status==='IN_PROGRESS')action=`<button class="primary" data-resume-session="${e.latest_session_id}">Resume exam</button>`;else if(e.exam_start_at&&e.exam_start_at>now)action=`<span class="badge">Starts ${new Date(e.exam_start_at*1000).toLocaleString()}</span>`;else if(['SUBMITTED','AUTO_SUBMITTED'].includes(e.latest_session_status)){const retake=e.student_allow_retake&&e.attempts_used<e.effective_max_attempts&&e.status==='OPEN'?`<button class="primary" data-start-exam="${e.id}">Retake exam</button>`:'';action=`<div class="actions"><button data-view-result="${e.latest_session_id}">View result</button>${retake}</div>`;}else if(e.registration_status==='COMPLETED')action='<span class="badge">Attempts completed</span>';else if(e.status==='CLOSED')action='<span class="badge">Exam closed</span>';else if(e.status!=='OPEN')action='<span class="badge">Waiting for administrator to open</span>';else action=`<button class="primary" data-start-exam="${e.id}">Enter proctor code</button>`;return examCard(e,action);}).join('')||'<p class="empty-state">You have not enrolled in an exam.</p>';}
async function loadMyResults(){const rows=await api('/api/my/results');$('my-results-list').innerHTML=rows.length?`<div class="result-history-grid">${rows.map(r=>{const pct=Number(r.percentage||0);const tone=pct>=80?'strong':pct>=50?'steady':'focus';return `<article class="panel result-history-card result-tone-${tone}"><div><span class="badge">${esc(r.exam_type||'Examination')}</span><h3>${esc(r.exam_name)}</h3><p><strong>${esc(r.subject||'General')}</strong> · ${esc(r.level||'All levels')} · Attempt ${r.attempt_number}</p></div><strong class="result-history-score">${pct.toFixed(1)}%</strong><span class="result-history-marks"><strong>${r.score}</strong> / ${r.max_score} marks</span><div class="result-history-actions"><button class="primary" data-review-attempt="${r.id}">Review result</button><button data-performance-exam="${r.exam_id}">Analysis</button></div></article>`;}).join('')}</div>`:'<p class="empty-state">No completed attempts yet.</p>';}
function resultHero(s,admin=false){const correct=Number(s.correct_count||0),incorrect=Number(s.incorrect_count||0),unanswered=Number(s.unanswered_count||0);return `<section class="result-hero"><div class="result-hero-top"><div><p class="eyebrow">${esc(s.exam_type||'EXAMINATION')} RESULT</p><h2>${esc(s.exam_name)}</h2><p class="result-student">${esc(s.student_name||s.student_email)} <span>${esc(s.student_email||'')}</span></p><div class="result-tags"><span>${esc(s.subject||'General')}</span><span>${esc(s.level||'All levels')}</span><span>Attempt ${s.attempt_number}</span><span>${s.submitted_at?new Date(s.submitted_at*1000).toLocaleString():'Completed'}</span></div></div><div class="result-score"><strong>${Number(s.percentage||0).toFixed(1)}%</strong><span>${s.score??0} / ${s.max_score??0} marks</span></div></div><div class="result-summary"><div><strong>${correct}</strong><span>Correct</span></div><div><strong>${incorrect}</strong><span>Incorrect</span></div><div><strong>${unanswered}</strong><span>Unanswered</span></div><div><strong>${correct+incorrect+unanswered}</strong><span>Questions</span></div></div><div class="ai-explanation-callout"><div><span class="ai-spark">AI</span><div><strong>Multilingual AI explanations</strong><p>Open any question for a structured explanation in English or తెలుగు, with concepts, reasoning, and practical exam tips.</p></div></div>${admin?'':`<button data-mentor="Explain my result" data-attempt="${s.id}">Ask IQraMentor</button>`}<button class="primary" data-performance-exam="${s.exam_id}" ${admin?`data-performance-student="${s.user_id}"`:''}>View examination analysis</button></div></section>`;}
function renderAttemptQuestions(target,questions,admin=false){target.insertAdjacentHTML('beforeend',`<div class="review-list">${questions.map((q,i)=>{const outcome=q.is_correct?'correct':q.selected_answer?'incorrect':'unanswered';return `<article class="panel attempt-review-card outcome-${outcome}"><div class="section-heading"><h3>Question ${i+1}</h3>${admin?'':`<div class="review-actions"><button class="mentor-action" data-mentor="Explain this question" data-attempt="${target.dataset.attempt||''}" data-question="${q.id}">Ask IQraMentor</button><button class="explain-action" data-explain="${q.id}">Explain in English / తెలుగు</button></div>`}</div><div class="rendered" data-${admin?'admin-':''}attempt-statement="${i}"></div><div class="attempt-answer-grid"><div class="answer-choice answer-selected"><span>${admin?'Student':'Your'} answer</span><div class="rendered" data-${admin?'admin-':''}attempt-selected="${i}"></div></div><div class="answer-choice answer-correct"><span>Correct answer</span><div class="rendered" data-${admin?'admin-':''}attempt-answer="${i}"></div></div></div><div class="attempt-solution"><strong>Solution</strong><div class="rendered" data-${admin?'admin-':''}attempt-solution="${i}"></div></div><span class="badge outcome-badge">${q.is_correct?'Correct':q.selected_answer?'Incorrect':'Unanswered'} · ${q.marks_awarded??0} marks</span></article>`;}).join('')}</div>`);questions.forEach((q,i)=>{const prefix=admin?'admin-':'';renderInto(target.querySelector(`[data-${prefix}attempt-statement="${i}"]`),q.statement||'');renderInto(target.querySelector(`[data-${prefix}attempt-selected="${i}"]`),q.selected_answer||'Unanswered');renderInto(target.querySelector(`[data-${prefix}attempt-answer="${i}"]`),q.answer||'');renderInto(target.querySelector(`[data-${prefix}attempt-solution="${i}"]`),q.solution||'No solution provided.');});}

async function loadAdminResults(){const rows=await api('/api/admin/results');$('admin-results-list').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Exam</th><th>Attempt</th><th>Score</th><th>Percentage</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.student_name||r.student_email)}<small>${esc(r.student_email)}</small></td><td>${esc(r.exam_name)}</td><td>${r.attempt_number}</td><td>${r.score??'—'} / ${r.max_score??'—'}</td><td>${r.percentage==null?'—':`${Number(r.percentage).toFixed(1)}%`}</td><td><span class="badge">${esc(r.status)}</span></td><td><button data-admin-review-attempt="${r.id}">View result</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-state">No completed exam attempts yet.</p>';}
document.addEventListener('click',async e=>{
  const nav=e.target.closest('[data-view]');if(nav){showView(nav.dataset.view);if(innerWidth<800)$('app-shell').classList.remove('nav-open');return;}
  const enroll=e.target.closest('[data-enroll]');if(enroll){try{await api(`/api/exams/${enroll.dataset.enroll}/enroll`,{method:'POST'});notify('Exam enrollment completed.');loadAvailableExams();}catch(err){notify(err.message);}return;}
  const start=e.target.closest('[data-start-exam]');if(start){try{const exam=await api(`/api/exams/${start.dataset.startExam}`);$('exam-start-modal').dataset.examId=exam.id;$('exam-start-title').textContent=exam.name;$('exam-start-details').innerHTML=`<p>You are registered for this examination.</p><dl><div><dt>Duration</dt><dd>${exam.duration_minutes} minutes</dd></div><div><dt>Questions</dt><dd>${exam.question_count}</dd></div><div><dt>Maximum marks</dt><dd>${exam.total_marks}</dd></div><div><dt>Attempts allowed</dt><dd>${exam.max_attempts}</dd></div></dl>`;$('proctor-code-field').hidden=!exam.proctor_required;$('student-proctor-code').value='';$('exam-start-status').textContent='';$('exam-start-modal').hidden=false;}catch(err){notify(err.message);}return;}
  const access=e.target.closest('[data-exam-access]');if(access){openExamAccess(access.dataset.examAccess);return;}
  const deleteExam=e.target.closest('[data-delete-exam]');if(deleteExam){if(!confirm(`Delete "${deleteExam.dataset.examName}" permanently?`))return;deleteExam.disabled=true;try{await api(`/api/admin/exams/${deleteExam.dataset.deleteExam}`,{method:'DELETE'});notify('Exam deleted.');$('exam-access-panel').hidden=true;await loadAdminExams();}catch(err){notify(err.message);}finally{deleteExam.disabled=false;}return;}
  const retake=e.target.closest('[data-toggle-retake]');if(retake){try{const enable=retake.dataset.enabled!=='1';await api(`/api/admin/exams/${retake.dataset.toggleRetake}/retake`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({allow_retake:enable,max_attempts:enable?Math.max(2,Number(retake.dataset.max)):1})});notify(enable?'Retakes enabled.':'Retakes disabled.');loadAdminExams();}catch(err){notify(err.message);}return;}
  const addQuestions=e.target.closest('[data-add-bank-questions]');if(addQuestions){addQuestions.disabled=true;try{const result=await api(`/api/admin/exams/${addQuestions.dataset.addBankQuestions}/questions/from-bank`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({count:15})});notify(`${result.added} Question Bank questions added.`);await loadAdminExams();}catch(err){notify(err.message);}finally{addQuestions.disabled=false;}return;}
  const generate=e.target.closest('[data-generate-for-exam]');if(generate){try{const exam=await api(`/api/exams/${generate.dataset.generateForExam}`);showView('exam');$('exam-blueprint-form').dataset.examId=exam.id;$('blueprint-name').value=exam.name||'';$('blueprint-type').value=exam.exam_type||'';$('blueprint-grade').value=exam.level||'';$('blueprint-duration').value=exam.duration_minutes||30;await loadBlueprintFacets();if(exam.subject&&!$('blueprint-subject').querySelector(`option[value="${CSS.escape(exam.subject)}"]`))$('blueprint-subject').add(new Option(exam.subject,exam.subject));$('blueprint-subject').value=exam.subject||'';notify('Saved exam template loaded. Configure the blueprint and generate its question paper.');}catch(err){notify(err.message);}return;}
  const paper=e.target.closest('[data-view-exam-paper]');if(paper){try{const result=await api(`/api/admin/exams/${paper.dataset.viewExamPaper}/paper`);showView('exam');$('exam-session-empty').hidden=false;$('exam-session').hidden=true;renderExamPaperToTab($('exam-paper-preview-tab'),result.questions);$('exam-paper-preview-tab').insertAdjacentHTML('afterbegin',`<div class="exam-paper-header"><strong>${esc(result.exam.name)}</strong><span>Permanent exam #${result.exam.id} · ${result.questions.length} questions</span></div>`);}catch(err){notify(err.message);}return;}
  const resume=e.target.closest('[data-resume-session]');if(resume){try{await enterExamFullscreen();await openSecureExam(resume.dataset.resumeSession);}catch(error){notify('Fullscreen permission is required to resume this secure exam.');}return;}
  const result=e.target.closest('[data-view-result]');if(result){document.body.classList.remove('exam-focus');showView('my-results');return;}
  const explain=e.target.closest('.attempt-review-card [data-explain]');if(explain){await openAttemptExplanation(explain.dataset.explain);return;}
  const performance=e.target.closest('[data-performance-exam]');if(performance){analyticsPendingExam=performance.dataset.performanceExam||'';analyticsPendingStudent=performance.dataset.performanceStudent||'';analyticsDimensionsLoaded=false;showView('student-analytics');return;}
  const review=e.target.closest('[data-review-attempt]');if(review){try{const data=await api(`/api/my/results/${review.dataset.reviewAttempt}`);if(!data.released){notify(data.message);return;}document.querySelectorAll('.tab-panel').forEach(p=>{p.hidden=p.id!=='my-results-panel';p.classList.toggle('active',!p.hidden);});const target=$('my-results-list');target.dataset.attempt=data.session.id;target.innerHTML=`<button class="result-back" onclick="loadMyResults()">← Attempt history</button>${resultHero(data.session)}`;renderAttemptQuestions(target,data.questions);}catch(err){notify(err.message);}return;}
  const adminReview=e.target.closest('[data-admin-review-attempt]');if(adminReview){try{const data=await api(`/api/admin/results/${adminReview.dataset.adminReviewAttempt}`),target=$('admin-results-list');target.innerHTML=`<button class="result-back" onclick="loadAdminResults()">← All student results</button>${resultHero(data.session,true)}`;renderAttemptQuestions(target,data.questions,true);}catch(err){notify(err.message);}return;}
});
async function openAttemptExplanation(questionId){const content=$('explain-content'),language=$('explain-language')?.value||'en';$('explain-modal').dataset.questionId=String(questionId);$('explain-modal').dataset.studentReview='1';content.textContent=language==='te'?'వివరణన సిద్ధం చేస్తున్నాం…':'Preparing an explanation…';$('explain-modal').hidden=false;$('explain-like').hidden=true;try{const data=await api(`/api/student/questions/${questionId}/explain?language=${encodeURIComponent(language)}`);renderStructuredExplanation(content,data);}catch(err){content.textContent=err.message;}}
$('explain-language')?.addEventListener('change',()=>{const modal=$('explain-modal');if(modal?.dataset.studentReview==='1'&&!modal.hidden&&modal.dataset.questionId)openAttemptExplanation(modal.dataset.questionId);});
async function openSecureExam(id){const data=await api(`/api/sessions/${id}`);if(data.session.status!=='IN_PROGRESS'){clearInterval(examTimerHandle);secureExamActive=false;document.body.classList.remove('exam-focus');await window.MeritIQraNative?.Native.examPosition({session:0});showView('my-results');notify('This assessment has ended. Your saved result is available.');return;}window.currentExamPolicy=data.exam;secureExamActive=!!data.exam.proctor_required;window.MeritIQraNative?.Native.protectedWindow({enabled:secureExamActive});$('exam-start-modal').hidden=true;document.body.classList.add('exam-focus');if(document.body.dataset.examDisplay==='focus')notify('Exam focus mode: this browser does not support fullscreen.');showView('exam');examQuestions=data.questions;examAnswers=Object.fromEntries(data.questions.map(q=>[q.number,q.selected_answer||'']));examCurrentIndex=0;examFinished=false;examState.questions=data.questions.map((q,index)=>({...q,_examKey:`exam-q-${index}-${q.id}`}));examState.answers=Object.fromEntries(examState.questions.map((q,index)=>[getExamQuestionKey(index),q.selected_answer]).filter(([,answer])=>answer));examState.markedForReview=new Set(data.questions.map((q,index)=>q.state&&q.state.includes('MARKED')?index:null).filter(index=>index!==null));examState.currentIndex=0;examState.started=true;examState.submitted=false;$('exam-session-empty').hidden=true;$('exam-session').hidden=false;$('exam-current-question').dataset.session=id;$('exam-current-question').dataset.expires=data.session.expires_at;renderExamSession();startServerTimer(id,data.session.expires_at,Number(data.server_time));if(window.MeritIQraNative)await window.restoreMobileAnswers?.(id);}
function startServerTimer(id,expires,serverTime){clearInterval(examTimerHandle);const offset=Number.isFinite(serverTime)?serverTime-Date.now()/1000:0;const tick=()=>{const left=Math.max(0,Math.floor(expires-(Date.now()/1000+offset)));$('exam-timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(!left){clearInterval(examTimerHandle);api(`/api/sessions/${id}/submit`,{method:'POST'}).then(()=>{secureExamActive=false;document.body.classList.remove('exam-focus');if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});showView('my-results');});}};tick();examTimerHandle=setInterval(tick,1000);}
document.addEventListener('change',e=>{const input=e.target.closest('.exam-option-item input');if(!input||!$('exam-current-question').dataset.session)return;const q=examState.questions[examState.currentIndex];examAnswers[q.number]=input.value;if(window.MeritIQraNative){window.saveMobileAnswer?.($('exam-current-question').dataset.session,q.id,input.value);return;}api(`/api/sessions/${$('exam-current-question').dataset.session}/answers/${q.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({selected_answer:input.value})}).then(()=>notify('Answer saved.')).catch(err=>notify(err.message));});
$('exam-submit-button').addEventListener('click',async()=>{if(window.MeritIQraNative&&!(await window.flushMobileAnswers?.()))return;const unanswered=examQuestions.filter(q=>!examAnswers[q.number]).length;if(!confirm(`You still have ${unanswered} unanswered question${unanswered===1?'':'s'}. Submit exam?`))return;try{await api(`/api/sessions/${$('exam-current-question').dataset.session}/submit`,{method:'POST'});clearInterval(examTimerHandle);secureExamActive=false;document.body.classList.remove('exam-focus');if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});showView('my-results');}catch(err){notify(err.message);}});
$('create-exam-toggle').onclick=()=>{$('create-exam-form').hidden=false;};$('create-exam-cancel').onclick=()=>{$('create-exam-form').hidden=true;};
$('create-exam-form').addEventListener('submit',async e=>{e.preventDefault();try{const stamp=id=>$(id).value?new Date($(id).value).getTime()/1000:null;await api('/api/admin/exams',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('new-exam-name').value,subject:$('new-exam-subject').value,exam_type:$('new-exam-type').value,level:$('new-exam-level').value,duration_minutes:Number($('new-exam-duration').value),max_attempts:Number($('new-exam-attempts').value),status:$('new-exam-status').value,description:$('new-exam-description').value,proctor_required:$('new-exam-proctor').checked,exam_start_at:stamp('new-exam-start'),exam_end_at:stamp('new-exam-end'),question_ids:$('new-exam-questions').value.split(',').map(Number).filter(Boolean)})});e.target.reset();e.target.hidden=true;notify('Exam created.');loadAdminExams();}catch(err){notify(err.message);}});
async function openExamAccess(examId){$('exam-access-panel').dataset.examId=examId;$('exam-access-panel').hidden=false;const [access,dashboard,registrations,sessions,results]=await Promise.all([api(`/api/admin/exams/${examId}/access`),api(`/api/proctor/exams/${examId}/dashboard`),api(`/api/admin/exams/${examId}/registrations`),api(`/api/admin/exams/${examId}/sessions`),api(`/api/admin/exams/${examId}/results`)]);$('exam-access-summary').textContent=`${access.exam.proctor_required?'Proctor code required':'No proctor code required'} · ${access.code?`${access.code.status}, ${access.code.usage_count} uses`:'No code generated'}`;const linked=registrations.linked.map(r=>`<tr><td>${esc(r.display_name||r.email)}</td><td>${esc(r.email)}</td><td><span class="badge">${esc(r.status)}</span></td><td>${r.attempts_used}</td><td><div class="actions"><select data-registration-status="${r.id}"><option value="ENROLLED" ${r.status==='ENROLLED'?'selected':''}>Enrolled</option><option value="BLOCKED" ${r.status==='BLOCKED'?'selected':''}>Blocked</option><option value="CANCELLED" ${r.status==='CANCELLED'?'selected':''}>Cancelled</option></select><span>${r.attempts_used} of ${r.effective_max_attempts} used</span><button class="primary" data-increase-attempts="${r.id}">Grant +1 attempt</button>${r.attempts_used?'<span>Retained with attempt history</span>':`<button class="danger" data-delete-registration="${r.id}" data-registration-kind="enrollment">Delete</button>`}</div></td></tr>`).join('');const pending=registrations.pending.map(r=>`<tr><td>Pending login</td><td>${esc(r.registered_email)}</td><td><span class="badge">${esc(r.status)}</span></td><td>0</td><td><div class="actions"><span>Links only to this verified email</span><button class="danger" data-delete-registration="${r.id}" data-registration-kind="pending">Delete</button></div></td></tr>`).join('');$('exam-monitor').innerHTML=`<div class="metric-strip"><div><span>Registered</span><strong>${dashboard.registered_students}</strong></div><div><span>Started</span><strong>${dashboard.students_started}</strong></div><div><span>Active</span><strong>${dashboard.currently_active}</strong></div><div><span>Submitted</span><strong>${dashboard.submitted}</strong></div></div><div class="actions"><button data-exam-state="PUBLISHED">Publish</button><button class="primary" data-exam-state="OPEN">Open exam</button><button data-exam-state="CLOSED">Close exam</button>${access.code&&access.code.status==='ACTIVE'?`<button data-revoke-code="${access.code.id}">Revoke code</button>`:''}</div><section class="conduct-section"><div class="section-heading"><div><h4>Registrations</h4><p>Pre-register an email or manage enrolled students.</p></div></div><div class="actions"><input id="admin-registration-email" type="email" placeholder="student@example.com" /><button class="primary" data-preregister-student>Pre-register email</button></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>Status</th><th>Attempts</th><th>Action</th></tr></thead><tbody>${linked}${pending||(!linked?'<tr><td colspan="5">No registrations yet.</td></tr>':'')}</tbody></table></div></section><section class="conduct-section"><h4>Recent sessions</h4><div class="table-wrap"><table><thead><tr><th>Student</th><th>Attempt</th><th>Answered</th><th>Started</th><th>Status</th></tr></thead><tbody>${sessions.map(s=>`<tr><td>${esc(s.display_name||s.email)}<small>${esc(s.email)}</small></td><td>${s.attempt_number}</td><td>${s.answered_count}</td><td>${new Date(s.started_at*1000).toLocaleString()}</td><td><span class="badge">${esc(s.status)}</span></td></tr>`).join('')||'<tr><td colspan="5">No sessions yet.</td></tr>'}</tbody></table></div></section><section class="conduct-section"><h4>Results</h4><div class="table-wrap"><table><thead><tr><th>Student</th><th>Attempt</th><th>Score</th><th>Percentage</th><th>Status</th></tr></thead><tbody>${results.map(r=>`<tr><td>${esc(r.display_name||r.email)}</td><td>${r.attempt_number}</td><td>${r.score} / ${r.max_score}</td><td>${Number(r.percentage).toFixed(1)}%</td><td><span class="badge">${esc(r.status)}</span></td></tr>`).join('')||'<tr><td colspan="5">No results yet.</td></tr>'}</tbody></table></div></section>`;$('exam-access-panel').scrollIntoView({behavior:'smooth'});}
