openExamAccess=async examId=>{await openExamAccessBase(examId);if(!$('generate-registration-link')){$('exam-monitor').insertAdjacentHTML('afterbegin','<div class="conduct-section"><h4>Student registration link</h4><p>Create a secure link to share with students.</p><div class="actions"><button id="generate-registration-link" class="primary">Generate registration link</button></div><div id="registration-link-result"></div></div>');$('generate-registration-link').onclick=async()=>{try{const result=await api(`/api/admin/exams/${examId}/registration-links`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('registration-link-result').innerHTML=`<label>Share this link<input value="${esc(result.url)}" readonly /></label><button id="copy-registration-link">Copy link</button>`;$('copy-registration-link').onclick=()=>navigator.clipboard.writeText(result.url).then(()=>notify('Registration link copied.'));}catch(err){notify(err.message);}};}};
