document.addEventListener('click',async event=>{const button=event.target.closest('[data-increase-attempts]');if(!button||!confirm('Grant this student one additional attempt?'))return;const examId=$('exam-access-panel').dataset.examId;button.disabled=true;try{const result=await api(`/api/admin/exams/${examId}/registrations/${button.dataset.increaseAttempts}/attempts/increase`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({increment:1})});notify(`Attempt allowance increased to ${result.max_attempts}.`);await openExamAccess(examId);}catch(err){notify(err.message);}finally{button.disabled=false;}});
let blueprintFacets={},blueprintPreview=null;
const facetOptions=(key,value='')=>`<option value="">Any</option>${(blueprintFacets[key]||[]).map(x=>`<option value="${esc(x.value)}" ${x.value===value?'selected':''}>${esc(x.value)} (${x.count})</option>`).join('')}`;
function addBlueprintRule(values={}){const index=$('blueprint-rules').children.length+1;const row=document.createElement('tr');row.dataset.ruleId=values.id||`rule-${index}`;row.innerHTML=`<td><select data-rule="chapter">${facetOptions('chapters',values.chapter)}</select></td><td><select data-rule="topic">${facetOptions('topics',values.topic)}</select></td><td><select data-rule="subtopic">${facetOptions('subtopics',values.subtopic)}</select></td><td><select data-rule="difficulty">${facetOptions('difficulties',values.difficulty)}</select></td><td><select data-rule="question_type">${facetOptions('question_types',values.question_type)}</select></td><td><input data-rule="count" type="number" min="1" max="200" value="${values.count||1}" /></td><td><button type="button" data-remove-blueprint-rule aria-label="Remove rule">Remove</button></td>`;$('blueprint-rules').append(row);updateBlueprintCount();}
function updateBlueprintCount(){const count=[...document.querySelectorAll('[data-rule="count"]')].reduce((n,x)=>n+Number(x.value||0),0);$('blueprint-count-summary').textContent=`Blueprint allocates ${count} of ${$('blueprint-total').value||0} questions`;}
function readBlueprint(){const statuses=$('blueprint-verification').value.split(',').filter(Boolean);const source=$('blueprint-source').value;return {exam_id:Number($('exam-blueprint-form').dataset.examId)||null,exam_name:$('blueprint-name').value.trim(),exam_type:$('blueprint-type').value.trim(),total_questions:Number($('blueprint-total').value),duration_minutes:Number($('blueprint-duration').value),prompt:$('blueprint-prompt').value.trim(),global_filters:{grade:$('blueprint-grade').value.trim(),subject:$('blueprint-subject').value,verification_statuses:statuses,source_types:source?[source]:[]},rules:[...$('blueprint-rules').children].map(row=>({id:row.dataset.ruleId,count:Number(row.querySelector('[data-rule="count"]').value),filters:Object.fromEntries([...row.querySelectorAll('[data-rule]:not([data-rule="count"])')].map(x=>[x.dataset.rule,x.value]).filter(([,v])=>v))})),allow_controlled_fallback:$('blueprint-fallback').checked,prefer_least_used:true,random_seed:Number($('blueprint-seed').value||0),exclude_question_ids:[]};}
async function loadBlueprintFacets(){const select=$('blueprint-subject');const current=select.value;const grade=$('blueprint-grade').value;const query=new URLSearchParams({grade,subject:current});blueprintFacets=await api(`/api/admin/question-metadata/facets?${query}`);if(!current&&grade&&!(blueprintFacets.subjects||[]).length)blueprintFacets=await api('/api/admin/question-metadata/facets');const subjects=[...(blueprintFacets.subjects||[])];if(current&&!subjects.some(x=>x.value===current))subjects.unshift({value:current,count:0});select.innerHTML='<option value="">Select subject</option>'+subjects.map(x=>`<option value="${esc(x.value)}">${esc(x.value)}${x.count?` (${x.count})`:''}</option>`).join('');select.value=current;}
function renderAvailability(data){const target=$('blueprint-availability');target.hidden=false;target.innerHTML=`<h3>Question availability</h3><div class="table-wrap"><table><thead><tr><th>Blueprint rule</th><th>Requested</th><th>Available</th><th>Status</th><th>Action</th></tr></thead><tbody>${data.rules.map(x=>`<tr><td>${esc(x.label)}</td><td>${x.requested}</td><td>${x.available}</td><td class="${x.status==='READY'?'blueprint-ready':'blueprint-shortage'}">${x.status}</td><td>${x.status==='SHORTAGE'?`<button type="button" class="primary" data-generate-shortage="${esc(x.rule_id)}" data-missing-count="${x.requested-x.available}">Generate missing ${x.requested-x.available} with AI</button>`:'Ready'}</td></tr>`).join('')}</tbody></table></div>${data.ready?'':'<p class="blueprint-shortage">Matching questions are insufficient. Generate the missing questions, save them to the Question Bank after review, then check availability again.</p>'}`;}
function openAiForBlueprintShortage(ruleId,missing){const bp=readBlueprint();const rule=bp.rules.find(x=>x.id===ruleId);if(!rule)return;showView('ai-generate');switchAiTab('new');const form=$('ai-generation-form');const values={exam_name:bp.exam_name,exam_type:bp.exam_type,level:bp.global_filters.grade||'',subject:bp.global_filters.subject||'',chapter:rule.filters.chapter||'',topic:rule.filters.topic||'',subtopic:rule.filters.subtopic||'',difficulty:rule.filters.difficulty||'',question_type:rule.filters.question_type||'',count:String(missing),generation_prompt:bp.prompt||`Generate ${missing} structurally complete questions that exactly match this examination blueprint. Use the specified grade, subject, chapter, topic, difficulty and question type. Provide valid answers, distinct options where applicable, and clear solutions.`};Object.entries(values).forEach(([name,value])=>{const field=form.elements.namedItem(name);if(field)field.value=value;});$('ai-generation-status').textContent=`Blueprint shortage loaded: generate ${missing} matching question${missing===1?'':'s'}, review them, and save them to the Question Bank.`;form.scrollIntoView({behavior:'smooth',block:'start'});}
$('blueprint-availability').addEventListener('click',e=>{const button=e.target.closest('[data-generate-shortage]');if(button)openAiForBlueprintShortage(button.dataset.generateShortage,Number(button.dataset.missingCount));});
function renderBlueprintPreview(data){blueprintPreview=data;const s=data.summary;$('blueprint-summary').hidden=false;$('blueprint-summary').innerHTML=`<h3>Exam generation summary</h3><div class="metric-strip"><div><span>Selected</span><strong>${s.selected}/${s.requested}</strong></div><div><span>Exact matches</span><strong>${s.exact_matches}</strong></div><div><span>Controlled fallback</span><strong>${s.fallback_matches}</strong></div></div><p><strong>Curriculum:</strong> ${Object.entries(s.chapter).map(([k,v])=>`${esc(k)} ${v}`).join(' · ')}</p><p><strong>Difficulty:</strong> ${Object.entries(s.difficulty).map(([k,v])=>`${esc(k)} ${v}`).join(' · ')}</p>`;const target=$('exam-paper-preview-tab');target.innerHTML=`<ol class="exam-paper-list">${data.questions.map((q,i)=>`<li class="exam-paper-item" data-blueprint-item="${q.id}" data-rule-id="${esc(q.rule_id)}"><div><label><input class="blueprint-question-select" type="checkbox" data-blueprint-question="${q.id}" checked />Include question #${q.id}</label> <button type="button" data-replace-blueprint-question="${q.id}">Replace with matching question</button></div><div class="exam-paper-meta"><span>${esc(q.chapter||'No chapter')}</span><span>${esc(q.topic||'Any topic')}</span><span>${esc(q.difficulty)}</span><span>${esc(q.qtype)}</span><span>${esc(q.source_type)}</span><span>${esc(q.verification_status)}</span><span>Used ${q.usage_count} times</span>${q.fallback?'<span>Controlled fallback</span>':''}</div><div class="rendered" data-blueprint-statement="${i}"></div></li>`).join('')}</ol>`;data.questions.forEach((q,i)=>renderInto(target.querySelector(`[data-blueprint-statement="${i}"]`),q.statement));$('blueprint-approval').hidden=false;updateBlueprintSelection();}
function updateBlueprintSelection(){$('blueprint-selection-count').textContent=`${document.querySelectorAll('[data-blueprint-question]:checked').length} questions selected`;}
$('blueprint-add-rule').onclick=()=>addBlueprintRule();$('blueprint-total').oninput=updateBlueprintCount;$('blueprint-rules').addEventListener('input',updateBlueprintCount);$('blueprint-rules').onclick=e=>{const button=e.target.closest('[data-remove-blueprint-rule]');if(button){button.closest('tr').remove();updateBlueprintCount();}};
$('blueprint-grade').addEventListener('change',loadBlueprintFacets);$('blueprint-subject').addEventListener('change',async()=>{await loadBlueprintFacets();const rules=[...$('blueprint-rules').children].map(row=>({id:row.dataset.ruleId,count:row.querySelector('[data-rule="count"]').value}));$('blueprint-rules').innerHTML='';rules.forEach(addBlueprintRule);});
$('blueprint-check').onclick=async()=>{try{renderAvailability(await api('/api/admin/exam-blueprints/availability',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(readBlueprint())}));}catch(err){notify(err.message);}};
$('exam-blueprint-form').onsubmit=async e=>{e.preventDefault();const button=$('blueprint-generate');button.disabled=true;try{const bp=readBlueprint();const availability=await api('/api/admin/exam-blueprints/availability',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(bp)});renderAvailability(availability);if(!availability.ready&&!bp.allow_controlled_fallback)throw new Error('Blueprint has shortages. Adjust it before generating.');renderBlueprintPreview(await api('/api/admin/exam-blueprints/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(bp)}));}catch(err){notify(err.message);}finally{button.disabled=false;}};
$('exam-paper-preview-tab').addEventListener('change',e=>{if(e.target.matches('[data-blueprint-question]'))updateBlueprintSelection();});
$('exam-paper-preview-tab').addEventListener('click',async e=>{const button=e.target.closest('[data-replace-blueprint-question]');if(!button)return;button.disabled=true;try{const item=button.closest('[data-blueprint-item]');const excluded=[...document.querySelectorAll('[data-blueprint-item]')].map(x=>Number(x.dataset.blueprintItem));const q=await api('/api/admin/exam-blueprints/replacement',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({blueprint:readBlueprint(),rule_id:item.dataset.ruleId,exclude_question_ids:excluded})});item.dataset.blueprintItem=q.id;item.querySelector('[data-blueprint-question]').dataset.blueprintQuestion=q.id;item.querySelector('label').lastChild.textContent=`Include question #${q.id}`;button.dataset.replaceBlueprintQuestion=q.id;item.querySelector('.exam-paper-meta').innerHTML=`<span>${esc(q.chapter||'No chapter')}</span><span>${esc(q.topic||'Any topic')}</span><span>${esc(q.difficulty)}</span><span>${esc(q.qtype)}</span><span>${esc(q.source_type)}</span><span>${esc(q.verification_status)}</span><span>Used ${q.usage_count} times</span>`;renderInto(item.querySelector('.rendered'),q.statement);notify('Question replaced within the same blueprint rule.');}catch(err){notify(err.message);}finally{button.disabled=false;}});
async function approveBlueprint(status,button){button.disabled=true;try{const selected=[...document.querySelectorAll('[data-blueprint-question]:checked')];const question_ids=selected.map(x=>Number(x.dataset.blueprintQuestion));const selection_rule_ids=Object.fromEntries(selected.map(x=>[x.dataset.blueprintQuestion,x.closest('[data-rule-id]').dataset.ruleId]));if(question_ids.length!==readBlueprint().total_questions)throw new Error('Select exactly the requested number of questions.');const result=await api('/api/admin/exam-blueprints/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({blueprint:readBlueprint(),question_ids,selection_rule_ids,status})});notify(`Durable exam #${result.id} created.`);showView('admin-exams');}catch(err){notify(err.message);}finally{button.disabled=false;}}
