function setWorkspace(mode){document.querySelectorAll('#analytics-limit,#analytics-days,#analytics-subject,#analytics-difficulty,#analytics-qtype').forEach(el=>el.parentElement.hidden=signedInUser?.role!=='STUDENT');document.querySelector('#student-analytics-panel [data-mentor]').hidden=signedInUser?.role!=='STUDENT';const admin=signedInUser?.role==='ADMIN';const studentMode=admin&&mode==='student';$('admin-nav').hidden=!admin||studentMode;$('student-nav').hidden=!(signedInUser?.role==='STUDENT'||studentMode);$('proctor-nav').hidden=signedInUser?.role!=='PROCTOR';$('workspace-switch').hidden=!admin;$('workspace-switch').textContent=studentMode?'Switch to admin workspace':'Switch to student view';$('workspace-switch').dataset.mode=studentMode?'student':'admin';$('account-role').textContent=studentMode?'ADMIN · Student view':signedInUser?.role||'';showView(signedInUser?.role==='PROCTOR'?'admin-exams':'dashboard');}
async function finishLogin(user){signedInUser=user;window.hidePublicSite?.();$('login-screen').hidden=true;$('app-header').hidden=false;$('app-shell').hidden=false;$('account-name').textContent=user.display_name||user.email;$('account-email').textContent=user.email;$('account-avatar').src=user.profile_picture||'';setWorkspace('admin');window.dispatchEvent(new CustomEvent('mobile:login',{detail:user}));const pending=sessionStorage.getItem('meritiqra_pending_exam');if(pending&&user.role==='STUDENT'){sessionStorage.removeItem('meritiqra_pending_exam');try{await api(`/api/exams/${Number(pending)}/enroll`,{method:'POST'});notify('Registration complete. The exam is now in My Exams.');showView('my-exams');}catch(error){notify(error.message);showView('available-exams');}}}
function renderGoogleSignIn(clientId,container,onUser,onError){container.textContent='Loading secure Google sign-in…';const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=()=>{container.textContent='';google.accounts.id.initialize({client_id:clientId,callback:async r=>{try{await onUser(await api('/api/auth/google',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({credential:r.credential})}));}catch(e){onError(e);}}});google.accounts.id.renderButton(container,{theme:'outline',size:'large',width:280,text:'continue_with'});};script.onerror=()=>{container.textContent='';onError(new Error('Google sign-in could not load. Check browser content blocking and reload this page.'));};document.head.append(script);}
async function bootstrapAuth(){try{return finishLogin(await api('/api/auth/me'));}catch{}const config=await fetch('/api/auth/config',{cache:'no-store'}).then(r=>r.json());if(window.MeritIQraNative){$('login-screen').hidden=false;$('app-shell').hidden=true;$('login-title').textContent='Continue with Gmail';$('google-signin').hidden=false;return;}window.showPublicSite?.();$('login-screen').hidden=false;$('bootstrap-admin-toggle').hidden=true;$('admin-login-toggle').hidden=true;$('admin-login-toggle').disabled=!config.local_admin;$('admin-login-email').value='';if(config.client_id){renderGoogleSignIn(config.client_id,$('google-signin'),finishLogin,e=>{$('login-message').textContent=e.message;});}else if(config.mock){$('mock-signin').hidden=false;}else $('login-message').textContent='Students and learners continue with Gmail. Administrator access is available from Admin Login.';}
$('bootstrap-admin-toggle').onclick=()=>{$('bootstrap-admin-toggle').hidden=true;$('bootstrap-admin-form').hidden=false;$('bootstrap-admin-name').focus();};
$('bootstrap-admin-cancel').onclick=()=>{$('bootstrap-admin-form').hidden=true;$('bootstrap-admin-toggle').hidden=false;};
$('bootstrap-admin-form').onsubmit=async e=>{e.preventDefault();$('login-message').textContent='Creating administrator…';try{await finishLogin(await api('/api/auth/bootstrap-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('bootstrap-admin-name').value,email:$('bootstrap-admin-email').value})}));}catch(err){$('login-message').textContent=err.message;}};
$('admin-login-toggle').onclick=()=>{$('admin-login-toggle').hidden=true;$('admin-login-form').hidden=false;$('admin-login-email').focus();};
$('admin-login-cancel').onclick=()=>{$('admin-login-form').hidden=true;$('admin-login-toggle').hidden=false;};
$('admin-login-form').onsubmit=async e=>{e.preventDefault();$('login-message').textContent='Signing in…';try{await finishLogin(await api('/api/auth/admin-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('admin-login-email').value,password:$('admin-login-password').value})}));}catch(err){$('login-message').textContent=err.message;}};
$('mock-signin').onclick=async()=>finishLogin(await api('/api/auth/mock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})}));
$('auth-logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});location.reload();};
$('login-close').onclick=()=>location.assign('/');
$('workspace-switch').onclick=()=>{setWorkspace($('workspace-switch').dataset.mode==='student'?'admin':'student');document.querySelectorAll('.account-menu[open]').forEach(panel=>panel.open=false);$('app-shell').classList.remove('nav-open');$('sidebar-toggle').setAttribute('aria-expanded','false');};
$('student-profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/student/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({full_name:$('profile-name').value,date_of_birth:$('profile-dob').value,phone_number:$('profile-phone').value,school_name:$('profile-school').value})});notify('Profile saved.');}catch(err){notify(err.message);}};
async function bootstrapPublicRegistration(){
  const match=location.pathname.match(/^\/register\/exam\/([^/]+)$/);if(!match)return false;
  const token=match[1];window.hidePublicSite?.();$('public-registration').hidden=false;
  try{
    const exam=await fetch(`/api/register/exam/${token}`,{cache:'no-store'}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.detail);return d;});
    $('public-exam-name').textContent=exam.name;$('public-exam-summary').textContent=`${exam.subject||'Examination'} · ${exam.duration_minutes} minutes`;
    if(window.setupSharedGoogleEnrollment&&await window.setupSharedGoogleEnrollment(token,exam))return true;
    $('public-fallback-toggle').textContent='Option 2 · Login without Gmail';$('public-new-registration').textContent='Register without Gmail';$('public-continue-login').textContent='Login without Gmail';
    const showRegistration=()=>{$('public-registration-form').hidden=false;$('public-student-login-form').hidden=true;$('public-new-registration').classList.add('primary');$('public-continue-login').classList.remove('primary');$('public-registration-message').textContent='';};
    const showStudentLogin=()=>{$('public-registration-form').hidden=true;$('public-student-login-form').hidden=false;$('public-new-registration').classList.remove('primary');$('public-continue-login').classList.add('primary');$('public-student-login-form').elements.email.focus();};
    $('public-new-registration').onclick=showRegistration;$('public-continue-login').onclick=showStudentLogin;
    const config=await fetch('/api/auth/config',{cache:'no-store'}).then(r=>r.json()).catch(()=>({}));
    if(config.client_id&&!window.MeritIQraNative){
      $('public-google-block').hidden=false;$('public-fallback').hidden=true;
      $('public-fallback-toggle').onclick=()=>{$('public-fallback').hidden=false;$('public-fallback-toggle').hidden=true;showRegistration();};
      renderGoogleSignIn(config.client_id,$('public-google-signin'),async user=>{history.replaceState({},'','/app');$('public-registration').hidden=true;await finishLogin(user);showView('my-exams');},err=>{$('public-registration-message').textContent=err.message;});
    }
    $('public-registration-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));try{const r=await fetch(`/api/register/exam/${token}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.detail);$('public-registration-message').textContent=d.message;const login=$('public-student-login-form');login.elements.email.value=body.email;login.elements.date_of_birth.value=body.date_of_birth;login.elements.phone_number.value=body.phone_number;showStudentLogin();$('public-registration-message').textContent=d.message;}catch(err){$('public-registration-message').textContent=err.message;}};
    $('public-student-login-form').onsubmit=async e=>{e.preventDefault();$('public-registration-message').textContent='Signing in…';try{const user=await api('/api/auth/student-registration-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});history.replaceState({},'','/app');$('public-registration').hidden=true;await finishLogin(user);showView('my-exams');}catch(err){$('public-registration-message').textContent=err.message;}};
  }catch(err){$('public-exam-summary').textContent=err.message;$('public-registration-form').hidden=true;}
  return true;
}
bootstrapPublicRegistration().then(active=>{if(!active)bootstrapAuth();});
window.addEventListener('load',()=>{if(signedInUser)showView('dashboard');});

// Secure exam browser controls. Client controls deter casual misuse while
// server audit events provide an enforceable violation trail.
document.addEventListener('copy',event=>{if(secureExamActive){event.preventDefault();recordSecurityViolation('COPY_ATTEMPT');}});
document.addEventListener('cut',event=>{if(secureExamActive){event.preventDefault();recordSecurityViolation('CUT_ATTEMPT');}});
document.addEventListener('paste',event=>{if(secureExamActive){event.preventDefault();recordSecurityViolation('PASTE_ATTEMPT');}});
document.addEventListener('contextmenu',event=>{if(secureExamActive){event.preventDefault();recordSecurityViolation('CONTEXT_MENU');}});
document.addEventListener('keydown',event=>{if(!secureExamActive)return;const key=event.key.toLowerCase();if(event.key==='F12'||(event.ctrlKey||event.metaKey)&&['c','x','v','p','s','u','t','n','w'].includes(key)||event.ctrlKey&&event.shiftKey&&['i','j','c'].includes(key)){event.preventDefault();recordSecurityViolation((key==='p')?'PRINT_ATTEMPT':(['t','n','w'].includes(key)?'TAB_SWITCH':'DEVTOOLS_SHORTCUT'));}});
document.addEventListener('visibilitychange',()=>{if(!window.MeritIQraNative&&secureExamActive&&document.hidden)recordSecurityViolation('TAB_SWITCH');});
window.addEventListener('blur',()=>{if(!window.MeritIQraNative&&secureExamActive)recordSecurityViolation('WINDOW_BLUR');});
document.addEventListener('fullscreenchange',()=>{if(secureExamActive&&document.body.dataset.examDisplay==='fullscreen'&&!document.fullscreenElement)recordSecurityViolation('FULLSCREEN_EXIT');});
window.addEventListener('beforeunload',event=>{if(!secureExamActive)return;recordSecurityViolation('NAVIGATION_ATTEMPT');event.preventDefault();event.returnValue='Your examination is still in progress.';});
$('exam-home')?.addEventListener('click',event=>{if(!secureExamActive)return;if(!confirm('Your exam is still in progress. Leave secure exam mode and return home? The active attempt will remain timed.'))event.preventDefault();else recordSecurityViolation('NAVIGATION_ATTEMPT');});
